using LedgerFlow.Api.Data;using LedgerFlow.Api.Models;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace LedgerFlow.Api.Controllers;[ApiController,Route("api/dashboard")]public sealed class DashboardController(AppDbContext db):ControllerBase{[HttpGet("metrics")]public async Task<IActionResult> Metrics(CancellationToken ct){var count=await db.Transactions.CountAsync(ct);var total=await db.Transactions.SumAsync(x=>x.Amount,ct);var exceptions=await db.Transactions.CountAsync(x=>x.Status==TransactionStatus.Exception,ct);var matched=await db.Transactions.CountAsync(x=>x.Status==TransactionStatus.Matched,ct);var rate=count==0?0:matched*100m/count;return Ok(new{transactionCount=count,settlementTotal=total,exceptionCount=exceptions,reconciliationRate=rate});}}
